using System.Text.Json.Nodes;
using Json.JsonE;

namespace LearnJsonEverything;

public class Lesson : ILessonRunner<JsonNode?>
{
    public JsonNode? Run(JsonObject test)
    {
        var template = test["template"];
        var context = test["context"]!.AsObject();

        context["safeDiv"] = JsonFunction.Create((parameters, _) =>
        {
            if (parameters.Length != 2) return null;
            if (parameters[0] is not JsonValue leftValue) return null;
            if (parameters[1] is not JsonValue rightValue) return null;
            if (!leftValue.TryGetValue<double>(out var left)) return null;
            if (!rightValue.TryGetValue<double>(out var right)) return null;
            if (right == 0) return null;

            return left / right;
        });

        return JsonE.Evaluate(template, context);
    }
}

